*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#17212b;font:16px/1.45 Arial,sans-serif}.wrap{max-width:1050px;margin:0 auto;padding:24px 18px 80px}header{display:flex;align-items:center;justify-content:space-between;gap:16px}h1{font-size:30px;margin:8px 0}.muted{color:#627386}.stats{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.stat,.panel,.person{background:white;border:1px solid #dce3eb;border-radius:14px}.stat{padding:15px 20px;min-width:160px}.stat strong{display:block;font-size:23px}.panel{padding:18px;margin:18px 0}.tabs{display:flex;gap:8px}.tabs button,.button{border:0;border-radius:9px;padding:11px 15px;font-size:16px;font-weight:700;cursor:pointer}.tabs button{background:#e6edf5;color:#26394b}.tabs button.active,.button{background:#0878f9;color:white}.button.secondary{background:#e6edf5;color:#26394b}.button.danger{background:#d92d20}.list{display:grid;grid-template-columns:repeat(auto-fill,minmax(310px,1fr));gap:12px;margin-top:14px}.person{padding:14px;display:grid;grid-template-columns:52px 1fr;gap:12px;align-items:start}.person img{width:52px;height:52px;border-radius:50%;object-fit:cover;background:#e9eef4}.name{font-weight:700}.name a{color:#17212b;text-decoration:none}.star{color:#d29a00;font-size:19px}.comment{margin:8px 0;padding:8px 10px;background:#fff7dc;border-radius:8px;white-space:pre-wrap;overflow-wrap:anywhere}.comment.empty{background:#f2f5f8;color:#6e7e8d}.tiny{font-size:14px}.comment-form{display:flex;gap:6px;margin-top:8px}.comment-form input{min-width:0;flex:1;padding:9px;border:1px solid #ccd6e0;border-radius:8px;font-size:14px}.message{padding:12px 14px;border-radius:10px;background:#e8f7ed;margin:14px 0}.error{background:#fff0ed;color:#a52a1a}.topform{display:inline}.person-actions{display:flex;gap:8px;align-items:center;margin-top:8px}.favorite{background:none;border:0;color:#526579;font-size:14px;cursor:pointer;padding:0}.check{display:flex;align-items:center;gap:7px}.check input{width:18px;height:18px}#friends .list{grid-template-columns:minmax(0,1fr);gap:7px}#friends .person{grid-template-columns:38px minmax(0,1fr);gap:8px;padding:8px;align-items:stretch}#friends .friend-select{display:flex;width:100%;height:100%;min-height:100%;align-items:center;justify-content:center;border-radius:8px;cursor:pointer}#friends .friend-select:hover{background:#edf4ff}#friends .check{width:19px;height:19px;cursor:pointer;accent-color:#0878f9}#friends .person img{width:36px;height:36px}#friends .comment{margin:4px 0;padding:5px 8px;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}#friends .comment-form{margin-top:4px}#friends .comment-form input{padding:6px 8px}.pagination{display:flex;align-items:center;justify-content:center;gap:14px;margin:16px 0 0;position:static;z-index:auto;background:#fff;border-top:1px solid #dce3eb;padding:10px 8px;box-shadow:0 -8px 14px -12px rgba(23,33,43,.45)}.pagination a{padding:7px 11px;border-radius:8px;background:#e6edf5;color:#26394b;text-decoration:none;font-weight:700}.pagination a:hover{background:#d5e6ff}.pagination.docked{position:fixed;bottom:0;z-index:20;margin:0}@media(max-width:600px){header{align-items:flex-start;flex-direction:column}.wrap{padding:16px 12px 80px}}
