<script>document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(item=>item.classList.toggle('active',item===button));document.querySelectorAll('.tab-content').forEach(section=>section.hidden=section.id!==button.dataset.tab)}));const hideFavorites=document.getElementById('hide-favorites');const selectButton=document.getElementById('toggle-select-friends');const visibleFriendCheckboxes=()=>[...document.querySelectorAll('#friends-list input[name="friends[]"]')].filter(checkbox=>!checkbox.closest('[data-favorite]')?.hidden);const updateSelectButton=()=>{if(!selectButton)return;const checkboxes=visibleFriendCheckboxes();selectButton.textContent=checkboxes.length>0&&checkboxes.every(checkbox=>checkbox.checked)?'Снять выбор':'Выбрать все'};if(selectButton){selectButton.addEventListener('click',()=>{const checkboxes=visibleFriendCheckboxes();const select=checkboxes.some(checkbox=>!checkbox.checked);checkboxes.forEach(checkbox=>checkbox.checked=select);updateSelectButton()});document.querySelectorAll('#friends-list input[name="friends[]"]').forEach(checkbox=>checkbox.addEventListener('change',updateSelectButton))}if(hideFavorites){hideFavorites.checked=sessionStorage.getItem('vk-hide-favorites')==='1';const applyFavoriteFilter=()=>{sessionStorage.setItem('vk-hide-favorites',hideFavorites.checked?'1':'0');document.querySelectorAll('#friends-list [data-favorite="1"]').forEach(person=>{person.hidden=hideFavorites.checked;if(hideFavorites.checked){const checkbox=person.querySelector('input[name="friends[]"]');if(checkbox)checkbox.checked=false}});updateSelectButton()};hideFavorites.addEventListener('change',applyFavoriteFilter);applyFavoriteFilter()}else{updateSelectButton()}</script>
<script>
const nameIdOnly=document.getElementById('name-id-only');
const friendsSection=document.getElementById('friends');
if(nameIdOnly&&friendsSection){
    nameIdOnly.checked=sessionStorage.getItem('vk-name-id-only')==='1';
    friendsSection.classList.toggle('only-name-id',nameIdOnly.checked);
    nameIdOnly.addEventListener('change',()=>{
        sessionStorage.setItem('vk-name-id-only',nameIdOnly.checked?'1':'0');
        friendsSection.classList.toggle('only-name-id',nameIdOnly.checked);
    });
}
</script>
<script>
document.addEventListener('submit',async(event)=>{
    const form=event.target.closest('.contact-row .favorite-form');
    if(!form)return;
    event.preventDefault();
    if(form.dataset.pending==='1')return;
    const row=form.closest('.friend-row');
    const favoriteInput=form.querySelector('input[name="is_favorite"]');
    const favoriteButton=form.querySelector('button');
    const error=document.createElement('span');
    let errorMessage=form.querySelector('.favorite-error');
    if(!errorMessage){errorMessage=error;error.className='favorite-error tiny';error.setAttribute('role','status');form.append(errorMessage)}
    const previous={favorite:row.dataset.favorite,hidden:row.hidden,selected:row.querySelector('input[name="friends[]"]')?.checked,input:favoriteInput.value,label:favoriteButton.textContent};
    const nextFavorite=favoriteInput.value==='1';
    const updateRow=(isFavorite)=>{
        row.dataset.favorite=isFavorite?'1':'0';
        row.hidden=Boolean(isFavorite&&row.closest('#friends')?.querySelector('#hide-favorites')?.checked);
        favoriteInput.value=isFavorite?'0':'1';
        favoriteButton.textContent=isFavorite?'★ Убрать':'☆ В избранное';
        if(row.hidden){const checkbox=row.querySelector('input[name="friends[]"]');if(checkbox)checkbox.checked=false}
        updateSelectButton();
    };
    const formData=new FormData(form);
    formData.set('is_favorite',nextFavorite?'1':'0');
    form.dataset.pending='1';favoriteButton.disabled=true;errorMessage.textContent='';updateRow(nextFavorite);
    try{
        const response=await fetch(form.action,{method:'POST',body:formData,credentials:'same-origin',headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});
        const result=await response.json();
        if(!response.ok||result.ok!==true)throw new Error(result.message||'Не удалось сохранить отметку.');
        updateRow(Boolean(result.is_favorite));
    }catch(_){
        row.dataset.favorite=previous.favorite;row.hidden=previous.hidden;favoriteInput.value=previous.input;favoriteButton.textContent=previous.label;
        const checkbox=row.querySelector('input[name="friends[]"]');if(checkbox)checkbox.checked=Boolean(previous.selected);
        errorMessage.textContent='Не удалось сохранить отметку. Попробуйте ещё раз.';updateSelectButton();
    }finally{delete form.dataset.pending;favoriteButton.disabled=false}
});
</script>
<script>
const removalButton=document.getElementById('start-friend-removal');
const removalStatus=document.getElementById('removal-status');
let removalTimer=null;
const showRemovalStatus=(message,isError=false,results=[])=>{
    removalStatus.hidden=false;
    removalStatus.classList.toggle('error',isError);
    removalStatus.replaceChildren();
    const heading=document.createElement('div');heading.textContent=message;removalStatus.append(heading);
    if(results.length){const list=document.createElement('ul');list.style.margin='8px 0 0';list.style.paddingLeft='22px';results.forEach(result=>{const row=document.createElement('li');row.textContent=`VK ID ${result.id}: ${result.label}`;list.append(row)});removalStatus.append(list)}
};
removalButton?.addEventListener('click',()=>{
    const ids=[...document.querySelectorAll('#friends-list input[name="friends[]"]:checked')].map(input=>input.value);
    if(!ids.length){showRemovalStatus('Сначала отметьте друзей на этой странице.',true);return}
    showRemovalStatus('Проверяю выбор и передаю его расширению Firefox…');
    clearTimeout(removalTimer);
    removalTimer=setTimeout(()=>{removalButton.disabled=false;showRemovalStatus('Нет ответа от расширения Firefox. Проверьте, что оно загружено в about:debugging, и обновите страницу.',true)},30000);
});
window.addEventListener('message',(event)=>{
    if(event.source!==window||event.origin!==location.origin||event.data?.type!=='VKFM_STATUS')return;
    const {phase,message,results=[]}=event.data;
    const done=['complete','stopped','error','cancelled'].includes(phase);
    clearTimeout(removalTimer);
    if(phase==='progress')removalButton.disabled=true;
    else if(done)removalButton.disabled=false;
    else removalTimer=setTimeout(()=>{removalButton.disabled=false;showRemovalStatus('Нет обновлений от расширения. Проверьте открывшуюся вкладку VK и при необходимости начните снова.',true,results)},30000);
    showRemovalStatus(message||'Статус обработки обновлён.',phase==='error'||phase==='stopped',results);
});
</script>
<script>
const syncHistoryButton=document.getElementById('sync-vk-history');
const syncHistoryStatus=document.getElementById('history-sync-status');
if(syncHistoryButton){syncHistoryButton.addEventListener('click',async()=>{syncHistoryButton.disabled=true;syncHistoryStatus.hidden=false;syncHistoryStatus.classList.remove('error');syncHistoryStatus.textContent='Загружаю полные списки друзей, подписчиков и исходящих заявок из VK…';try{const response=await fetch('/history/sync',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content}});const payload=await response.json();if(!response.ok)throw new Error(payload.message||'Не удалось обновить состояние.');for(const [key,value] of Object.entries(payload.summary||{})){const node=document.querySelector(`[data-db-stat="${key}"]`);if(node)node.textContent=value??0}const dateOptions={day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'};const observed=document.getElementById('last-observed-at');const fullSync=document.getElementById('last-full-sync-at');if(observed)observed.textContent=payload.summary.last_observed_at?new Date(payload.summary.last_observed_at).toLocaleString('ru-RU',dateOptions):'ещё не было';if(fullSync)fullSync.textContent=payload.summary.last_full_sync_at?new Date(payload.summary.last_full_sync_at).toLocaleString('ru-RU',dateOptions):'ещё не было';syncHistoryStatus.textContent=`Сверка завершена: друзей ${payload.friends}, подписчиков ${payload.followers}, исходящих заявок ${payload.outgoing_requests}. Новых или изменённых статусов: ${payload.changed}; закрыто устаревших записей: ${payload.staled}.`}catch(error){syncHistoryStatus.classList.add('error');syncHistoryStatus.textContent=error.message||'Не удалось обновить состояние.'}finally{syncHistoryButton.disabled=false}})}
const updatePaginationDock=()=>{
    document.querySelectorAll('.pagination.docked').forEach(nav=>{nav.classList.remove('docked');nav.style.left='';nav.style.width=''});
    const activeSection=[...document.querySelectorAll('.tab-content')].find(section=>!section.hidden);
    const pagination=activeSection?.querySelector('.pagination');
    if(!pagination)return;
    const pageBottom=window.scrollY+window.innerHeight>=document.documentElement.scrollHeight-2;
    if(pageBottom)return;
    const panel=pagination.closest('.panel');
    const bounds=panel?.getBoundingClientRect();
    if(!bounds)return;
    pagination.classList.add('docked');
    pagination.style.left=`${bounds.left}px`;
    pagination.style.width=`${bounds.width}px`;
};
window.addEventListener('scroll',updatePaginationDock,{passive:true});
window.addEventListener('resize',updatePaginationDock);
document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>requestAnimationFrame(updatePaginationDock)));
requestAnimationFrame(updatePaginationDock);
</script></body></html>
